/* Koruk Asistan v2 generated bundle: dashboard.js. Kaynak dosyaları düzenleyin; bu dosyayı elle düzenlemeyin. */

/* ===== SOURCE: js/modules/dashboard.js ===== */
/* Koruk Asistan V2 — Ana Sayfa
 * Eski admin/öğretmen ana sayfa hiyerarşisi local-first mimaride yeniden kurulur.
 * Kalıcı veri kaynağı AppStore/DeviceData; Firestore yalnız SyncEngine arka planıdır.
 */
(function(){
'use strict';if(window.DashboardModule)return;
let mounted=false,unsubs=[],reminderShown=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[c]));
const arr=t=>{const v=window.AppStore?.data?.(t);return Array.isArray(v)?v:[]};
function isoToday(){const d=new Date(),p=n=>String(n).padStart(2,'0');return`${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`}
function date(v){if(!v)return'—';try{if(typeof v.toDate==='function')return v.toDate().toLocaleDateString('tr-TR');const d=new Date(String(v).length===10?v+'T00:00:00':v);return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString('tr-TR')}catch(_){return String(v)}}
function user(){return window.AppStore?.get?.('session.user')||window.AKTIF_KULLANICI||{}}
function isAdmin(){return user().admin===true}
function firstName(){const u=user(),ad=u.ad||u.adSoyad||u.displayName||u.kullaniciAdi||'';return String(ad).trim().split(/\s+/)[0]||'Kullanıcı'}
function teacherId(){const u=user();return u.bagliOgretmenId||u.ogretmenId||''}
function greeting(){const h=new Date().getHours();return h<6?'İyi geceler':h<12?'Günaydın':h<18?'İyi günler':'İyi akşamlar'}
function upcoming(list,field,days=14){const now=new Date(isoToday()+'T00:00:00'),max=new Date(now.getTime()+days*86400000);return list.filter(x=>{if(!x?.[field])return false;const d=new Date(String(x[field]).slice(0,10)+'T00:00:00');return !Number.isNaN(d.getTime())&&d>=now&&d<=max}).sort((a,b)=>String(a[field]).localeCompare(String(b[field])))}
function cards(){return(window.AppConfig?.dashboardCards?.()||[{key:'welcome',visible:true,order:10},{key:'stats',visible:true,order:20},{key:'upcoming',visible:true,order:30},{key:'announcements',visible:true,order:40},{key:'duty',visible:true,order:50}]).filter(x=>x.visible!==false).sort((a,b)=>Number(a.order||0)-Number(b.order||0))}
function cardVisible(key){return cards().map(x=>x.key).includes(key)}
const DAY_NAMES=['Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi'];
function dayName(d=new Date()){return DAY_NAMES[d.getDay()]}
function dayLong(d=new Date()){return d.toLocaleDateString('tr-TR',{weekday:'long',day:'numeric',month:'long'})}
function normalizeDay(v){return String(v||'').toLocaleLowerCase('tr').replace(/ı/g,'i').replace(/ş/g,'s').replace(/ğ/g,'g').replace(/ü/g,'u').replace(/ö/g,'o').replace(/ç/g,'c')}
function sameDay(a,b){return normalizeDay(a)===normalizeDay(b)}
function sortHour(a,b){return String(a?.saat??a?.dersSaati??'').localeCompare(String(b?.saat??b?.dersSaati??''),'tr',{numeric:true})}
function lessonLabel(x){return x.ders||x.dersAdi||x.brans||'Ders'}
function classLabel(x){return x.sinif||x.sinifAdi||x.sube||'Sınıf'}
function teacherLabel(x){if(x.ogretmenAdSoyad||x.ogretmenAdi)return x.ogretmenAdSoyad||x.ogretmenAdi;const t=arr('ogretmenler').find(o=>o.id===x.ogretmenId);return t?.adSoyad||[t?.ad,t?.soyad].filter(Boolean).join(' ')||'Öğretmen'}
function todayLessons({mine=false}={}){const tid=teacherId(),name=dayName();return arr('dersProgrami').filter(x=>sameDay(x.gun,name)&&(!mine||!tid||x.ogretmenId===tid)).sort(sortHour)}
function isDone(x){return x?.tamamlandi===true||['Tamamlandı','Tamamlandi','tamamlandi'].includes(x?.durum)}
function section(title,icon,id,body,extra=''){return `<section class="ka-home-section ${extra}" data-home-section="${id}"><div class="ka-home-section__head"><div><span class="ka-home-section__icon">${icon}</span><h3>${esc(title)}</h3></div></div><div class="ka-home-section__body">${body}</div></section>`}
function empty(text){return `<div class="ka-home-empty">${esc(text)}</div>`}
function routeButton(label,module,icon='→'){return `<button class="ka-home-link" type="button" data-dash-route="${module}"><span>${esc(label)}</span><b>${icon}</b></button>`}
function hero(){const mine=todayLessons({mine:true}),next=mine[0],reminders=teacherId()?collectReminders().filter(x=>x.gunFarki<=3).length:0;return `<section class="ka-home-hero" data-dashboard-card="welcome"><div class="ka-home-hero__top"><div><span>${esc(greeting())},</span><h1>${esc(firstName())} 👋</h1><small>${esc(dayLong())}</small></div><span class="ka-home-hero__badge">${isAdmin()?'Yönetici':'Öğretmen'}${reminders?` · 🔔 ${reminders}`:''}</span></div>${next?`<div class="ka-home-lesson-focus"><div><small>Bugünkü ilk dersiniz</small><strong>${esc(lessonLabel(next))}</strong><span>${esc(classLabel(next))}${next.saat?` · ${esc(next.saat)}. ders`:''}</span></div>${routeButton('Programım','academic','›')}</div>`:`<div class="ka-home-hero__quiet">${isAdmin()?'Yönetim özeti cihaz verilerinden hazırlandı.':'Bugün için kişisel ders kaydı görünmüyor.'}</div>`}</section>`}
function announcementSection(){if(!cardVisible('announcements'))return'';const list=arr('duyurular').filter(x=>x.arsivlendi!==true&&x.aktif!==false).sort((a,b)=>String(b.tarih||b.eklenmeTarihi||'').localeCompare(String(a.tarih||a.eklenmeTarihi||''))).slice(0,3);const body=list.length?list.map((x,i)=>`<article class="ka-home-announcement"><span class="ka-home-announcement__mark">${i===0?'📣':'•'}</span><div><strong>${esc(x.baslik||'Duyuru')}</strong><p>${esc(String(x.icerik||x.aciklama||'').replace(/<[^>]*>/g,'').slice(0,150))}</p>${x.tarih?`<small>${esc(date(x.tarih))}</small>`:''}</div></article>`).join(''):empty('Aktif duyuru yok.');return section('Duyurular','📣','announcements',body)}
function pollSection(){const list=arr('anketler').filter(x=>x.aktif!==false&&x.arsivlendi!==true).slice(0,2);if(!list.length)return'';return section('Aktif Anketler','📊','polls',list.map(x=>`<article class="ka-home-row"><span class="ka-home-rowicon">📊</span><div class="ka-grow"><strong>${esc(x.baslik||x.soru||'Anket')}</strong><small>${esc(x.aciklama||'Katılım bekleniyor')}</small></div></article>`).join(''))}
function newsSection(){const list=arr('haberler').filter(x=>x.aktif!==false).sort((a,b)=>String(b.tarih||b.eklenmeTarihi||'').localeCompare(String(a.tarih||a.eklenmeTarihi||''))).slice(0,5);if(!list.length)return'';return section('Kayan Haberler','📰','news',`<div class="ka-home-news-strip">${list.map(x=>`<article><strong>${esc(x.baslik||'Haber')}</strong><span>${esc(String(x.ozet||x.aciklama||x.icerik||'').replace(/<[^>]*>/g,'').slice(0,100))}</span></article>`).join('')}</div>`)}
function statCard(icon,label,value){return `<article class="ka-home-stat"><span>${icon}</span><div><b>${esc(String(value))}</b><small>${esc(label)}</small></div></article>`}
function statsSection(){if(!cardVisible('stats'))return'';return section('Okul Özeti','▥','stats',`<div class="ka-home-stats">${statCard('👥','Öğretmen',arr('ogretmenler').length)}${statCard('🎓','Öğrenci',arr('veliler').length)}${statCard('🏫','Sınıf',arr('siniflar').length)}${statCard('🚌','Servis',arr('servisler').length)}</div>`)}
function dutyRows(list){const places=arr('nobetYerleri');return list.map(x=>{const p=places.find(y=>y.id===x.yerId);return `<article class="ka-home-row"><span class="ka-home-avatar">${esc((teacherLabel(x).split(/\s+/).slice(0,2).map(s=>s[0]).join('')||'N').toLocaleUpperCase('tr'))}</span><div class="ka-grow"><strong>${esc(teacherLabel(x))}</strong><small>${esc(x.yerAdi||p?.ad||'Nöbet yeri')}</small></div>${x.defterDolduruldu?'<span class="ka-badge ka-badge--success">Tamam</span>':''}</article>`}).join('')}
function dutySection(){if(!cardVisible('duty'))return'';const list=arr('nobetAtamalari').filter(x=>String(x.tarih||'').slice(0,10)===isoToday());return section(isAdmin()?"Bugünün Nöbetçileri":'Nöbetim','🛡️','duty',list.length?dutyRows(isAdmin()?list:list.filter(x=>!teacherId()||x.ogretmenId===teacherId())):empty('Bugün için nöbet kaydı yok.'))}
function absencesSection(){if(!isAdmin())return'';const today=isoToday(),active=[...arr('personelIzinler'),...arr('ogretmenIzinleri')].filter(x=>{const a=String(x.baslangicTarihi||x.baslangic||x.tarih||'').slice(0,10),b=String(x.bitisTarihi||x.bitis||x.tarih||a).slice(0,10);return a&&a<=today&&(!b||b>=today)});if(!active.length)return'';return section('Bugün İzinli Olanlar','🏠','absences',active.map(x=>`<article class="ka-home-row"><span class="ka-home-rowicon">🏠</span><div class="ka-grow"><strong>${esc(x.adSoyad||x.personelAdi||x.ogretmenAdi||teacherLabel(x))}</strong><small>${esc(x.izinTuru||x.tur||x.aciklama||'İzinli')}</small></div></article>`).join(''))}
function upcomingRows(){const exams=upcoming([...arr('sinavlar'),...arr('denemeSinavlari')],'tarih',14).map(x=>({icon:'📝',title:x.ad||x.ders||x.sinavAdi||'Sınav',meta:`${date(x.tarih)} · Sınav`}));const reminders=upcoming(arr('hatirlaticilar'),'tarih',14).filter(x=>!x.tamamlandi).map(x=>({icon:'🔔',title:x.baslik||'Hatırlatıcı',meta:`${date(x.tarih)} · Hatırlatıcı`}));const tasks=upcoming(arr('gorevler'),'sonTarih',14).filter(x=>!isDone(x)).map(x=>({icon:'✓',title:x.baslik||'Görev',meta:`${date(x.sonTarih)} · Görev`}));return[...exams,...reminders,...tasks].sort((a,b)=>a.meta.localeCompare(b.meta)).slice(0,8)}
function upcomingSection(){if(!cardVisible('upcoming'))return'';const rows=upcomingRows();return section(isAdmin()?'Yaklaşan Görevler':'Teslim & Görev Takvimi','📅','upcoming',rows.length?rows.map(r=>`<article class="ka-home-row"><span class="ka-home-rowicon">${r.icon}</span><div class="ka-grow"><strong>${esc(r.title)}</strong><small>${esc(r.meta)}</small></div></article>`).join(''):empty('Yaklaşan kayıt yok.'))}
function lessonsSection(){const mine=!isAdmin()&&!!teacherId(),all=todayLessons({mine});let list=all,title=mine?'Bugünkü Derslerim':'Şu Anki Dersler';if(isAdmin()){const live=window.SchoolLiveStatus?.status?.(),period=live?.mode==='lesson'?live.period:live?.nextPeriod;if(period)list=all.filter(x=>Number(x.saat??x.dersSaati)===Number(period));else if(['after','weekend'].includes(live?.mode))list=[];title=live?.mode==='lesson'?'Şu Anki Dersler':live?.nextPeriod?`Sonraki Dersler · ${live.nextPeriod}. Ders`:'Şu Anki Dersler'}return section(title,'📚','lessons',list.length?`<div class="ka-home-lessons">${list.slice(0,10).map(x=>`<article ${mine?`data-dash-lesson-plan data-lesson="${esc(lessonLabel(x))}" data-class="${esc(classLabel(x))}"`:`data-dash-route="academic"`}><span>${esc(String(x.saat??x.dersSaati??'•'))}</span><div><strong>${esc(lessonLabel(x))}</strong><small>${esc(classLabel(x))}${mine?' · Haftalık kazanımlar':` · ${esc(teacherLabel(x))}`}</small></div></article>`).join('')}</div>`:empty(isAdmin()?'Bu ders saati için program kaydı yok.':'Bugün için ders programı kaydı yok.'))}
function weekRange(){const d=new Date(),day=(d.getDay()+6)%7,monday=new Date(d);monday.setDate(d.getDate()-day);monday.setHours(0,0,0,0);const sunday=new Date(monday);sunday.setDate(monday.getDate()+6);return[monday,sunday]}
function weekDutySection(){if(!isAdmin())return'';const[a,b]=weekRange(),list=arr('nobetAtamalari').filter(x=>{const d=new Date(String(x.tarih||'').slice(0,10)+'T00:00:00');return!Number.isNaN(d.getTime())&&d>=a&&d<=b}).sort((x,y)=>String(x.tarih).localeCompare(String(y.tarih)));if(!list.length)return'';return section('Haftalık Nöbet Programı','🗓️','week-duty',`<div class="ka-home-week-duty">${list.slice(0,12).map(x=>`<article><time>${esc(new Date(x.tarih+'T00:00:00').toLocaleDateString('tr-TR',{weekday:'short',day:'numeric'}))}</time><strong>${esc(teacherLabel(x))}</strong><small>${esc(x.yerAdi||arr('nobetYerleri').find(p=>p.id===x.yerId)?.ad||'')}</small></article>`).join('')}</div>`)}
function examsSection(){const tid=!isAdmin()?teacherId():'',list=upcoming(arr('sinavlar'),'tarih',30).filter(x=>!tid||x.ogretmenId===tid).slice(0,6);if(!list.length)return'';return section(tid?'Sınavlarım':'Yaklaşan Sınavlar','📝','exams',list.map(x=>`<article class="ka-home-row"><span class="ka-home-datebox"><b>${esc(String(new Date(x.tarih+'T00:00:00').getDate()))}</b><small>${esc(new Date(x.tarih+'T00:00:00').toLocaleDateString('tr-TR',{month:'short'}))}</small></span><div class="ka-grow"><strong>${esc(x.ders||x.ad||x.sinavAdi||'Sınav')}</strong><small>${esc(x.sinif||x.sinifAdi||'')}${x.saat?` · ${esc(x.saat)}`:''}</small></div></article>`).join(''))}
function personalScheduleSection(){const tid=!isAdmin()?teacherId():'';if(!tid)return'';const list=arr('dersProgrami').filter(x=>x.ogretmenId===tid).sort((a,b)=>{const ai=DAY_NAMES.indexOf(a.gun),bi=DAY_NAMES.indexOf(b.gun);return(ai-bi)||sortHour(a,b)});if(!list.length)return'';return section('Ders Programım','⏱️','schedule',`<div class="ka-home-schedule">${DAY_NAMES.slice(1,6).map(g=>{const rows=list.filter(x=>sameDay(x.gun,g));return rows.length?`<div><strong>${g}</strong><span>${rows.map(x=>`${esc(String(x.saat??'•'))}. ${esc(classLabel(x))}`).join(' · ')}</span></div>`:''}).join('')}</div>${routeButton('Tüm programı aç','academic','›')}`)}
function notesSection(){const u=user(),list=arr('notlar').filter(x=>u.admin||!x.sahipUid||x.sahipUid===u.uid).sort((a,b)=>String(b.tarih||b.olusturmaTarihi||'').localeCompare(String(a.tarih||a.olusturmaTarihi||''))).slice(0,4);return section('Notlarım','📒','notes',list.length?list.map(x=>`<article class="ka-home-note"><strong>${esc(x.baslik||'Not')}</strong><p>${esc(String(x.icerik||x.not||x.metin||'').slice(0,130))}</p></article>`).join(''):empty('Henüz notunuz yok.'))}
function quickSection(){return section('Hızlı İşlemler','⚡','quick',`<div class="ka-home-quick"><button type="button" data-dash-route="academic" data-dash-page="written" data-dash-title="Yazılı Sınavlar"><span>📝</span><b>Sınav Ekle</b></button><button type="button" data-dash-route="communication" data-dash-page="messages" data-dash-title="Mesajlaşma"><span>💬</span><b>Mesaj Gönder</b></button><button type="button" data-dash-route="documents" data-dash-title="Dokümanlar"><span>📄</span><b>Dokümanlar</b></button><button type="button" data-dash-quick-note><span>📒</span><b>Hızlı Not</b></button></div>`)}
function calendarSection(){if(isAdmin())return'';const now=new Date(),days=[];for(let i=0;i<7;i++){const d=new Date(now);d.setDate(now.getDate()+i);const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const count=arr('gorevler').filter(x=>String(x.sonTarih||x.tarih||'').slice(0,10)===iso&&!isDone(x)).length+arr('hatirlaticilar').filter(x=>String(x.tarih||'').slice(0,10)===iso&&!x.tamamlandi).length+arr('sinavlar').filter(x=>String(x.tarih||'').slice(0,10)===iso).length;days.push({d,count})}return section('Takvim','📆','calendar',`<div class="ka-home-calendar">${days.map((x,i)=>`<article class="${i===0?'today':''}"><small>${esc(x.d.toLocaleDateString('tr-TR',{weekday:'short'}))}</small><b>${x.d.getDate()}</b>${x.count?`<span>${x.count}</span>`:'<i></i>'}</article>`).join('')}</div>${routeButton('Takvimi aç','communication','›')}`)}
function adminShell(){return`${cardVisible('welcome')?hero():''}${announcementSection()}${pollSection()}${newsSection()}${statsSection()}${dutySection()}${absencesSection()}${upcomingSection()}${lessonsSection()}${weekDutySection()}${examsSection()}${notesSection()}`}
function teacherShell(){return`${cardVisible('welcome')?hero():''}${announcementSection()}${newsSection()}${lessonsSection()}${dutySection()}${upcomingSection()}${quickSection()}${examsSection()}${personalScheduleSection()}${notesSection()}${calendarSection()}`}
function shell(){const configured=cards().map(x=>x.key).join('|');return`<section class="ka-home" data-dashboard-module data-dashboard-role="${isAdmin()?'admin':'teacher'}" data-card-signature="${esc(configured)}">${isAdmin()?adminShell():teacherShell()}</section>`}
function bindPresentation(root){
  root.querySelectorAll('[data-dash-route]').forEach(btn=>btn.addEventListener('click',()=>window.ShellUI?.routeModule?.(btn.dataset.dashRoute,{bottom:'menu',page:btn.dataset.dashPage||'',title:btn.dataset.dashTitle||''})));
  root.querySelectorAll('[data-dash-lesson-plan]').forEach(btn=>btn.addEventListener('click',async()=>{const ok=await window.ShellUI?.routeModule?.('academic',{bottom:'menu',title:'Yıllık Plan'});if(ok===false)return;const opened=await window.AcademicModule?.openPlanForLesson?.(btn.dataset.lesson||'',btn.dataset.class||'');if(opened===false)window.toast?.('Bu ders ve sınıf için eşleşen yıllık plan bulunamadı.')}));
  root.querySelector('[data-dash-quick-note]')?.addEventListener('click',()=>window.ShellUI?.openQuickNote?.())
}

/* ========================= LOCAL-FIRST HATIRLATMA MOTORU ========================= */
const REMINDER_DEFS={evrakTakibi:'evrak',sosyalKulupler:'sosyalKulupler',rehberlik:'rehberlik',maarifRapor:'maarifRapor',zumre:'zumre',sok:'sok',bepPlani:'bepPlani',belirliGunler:'belirliGunler',kontrolListeleri:'kontrolListeleri',kontrolListeTamamlama:'kontrolListeTamamlama',hatirlatmaAyarlari:'hatirlatmaAyarlari',dersSaatleri:'dersSaatleri',personelIzinler:'personelIzinler',ogretmenIzinleri:'ogretmenIzinleri',anketler:'anketler'};
const MONTH_NAMES=['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];
const MONTHLY={sosyalKulupler:{aylar:['Eki','Kas','Ara','Oca','Şub','Mar','Nis','May','Haz'],start:2,label:'Sosyal Kulüp Aylık Rapor',teacherField:'ogretmenIdler'},rehberlik:{aylar:['Eki','Kas','Ara','Oca','Şub','Mar','Nis','May','Haz'],start:1,label:'Rehberlik Aylık Rapor',teacherField:'ogretmenId'},maarifRapor:{aylar:['Eyl','Eki','Kas','Ara','Oca','Şub','Mar','Nis','May','Haz'],start:0,label:'Maarif Model Aylık Rapor',teacherField:'ogretmenId'}};
const ONE_OFF=[{type:'sosyalKulupler',field:'yillikPlanTarihi',index:0,label:'Sosyal Kulüp — Yıllık Plan',teacherField:'ogretmenIdler'},{type:'sosyalKulupler',field:'toplumHizmetiTarihi',index:1,label:'Sosyal Kulüp — Toplum Hizmeti Planı',teacherField:'ogretmenIdler'},{type:'rehberlik',field:'yillikPlanTarihi',index:0,label:'Rehberlik — Yıllık Çalışma Planı',teacherField:'ogretmenId'},{type:'bepPlani',field:'yillikDersPlaniTarihi',index:0,label:'Yıllık Ders Planı',teacherField:'ogretmenId'},{type:'bepPlani',field:'bepPlaniTarihi',index:1,label:'BEP Planı',teacherField:'ogretmenId'}];
function reminderSettings(){return{gunSayisi:3,erteleSaat:4,...(arr('hatirlatmaAyarlari').find(x=>x.id==='ayarlar')||arr('hatirlatmaAyarlari')[0]||{})}}
function dayDiff(iso){if(!iso)return 99999;const a=new Date(isoToday()+'T00:00:00'),b=new Date(String(iso).slice(0,10)+'T00:00:00');return Number.isNaN(b.getTime())?99999:Math.round((b-a)/86400000)}
function nextMonthFirstWeek(year,month0){let m=month0+1,y=year;if(m>11){m=0;y++}return`${y}-${String(m+1).padStart(2,'0')}-07`}
function academicMonthDeadline(shortName){const idx=MONTH_NAMES.indexOf(shortName);if(idx<0)return null;const now=new Date();let iso=nextMonthFirstWeek(now.getFullYear(),idx);if(new Date(iso+'T00:00:00')>now)iso=nextMonthFirstWeek(now.getFullYear()-1,idx);return iso}
function belongs(row,id,field){return field==='ogretmenIdler'?(row?.[field]||[]).includes(id):row?.[field]===id}
function route(module){return()=>{if(window.ShellUI?.routeModule)return window.ShellUI.routeModule(module,{bottom:'menu'});document.querySelector(`[data-ka-module="${module}"]`)?.click()}}
function reminder(type,title,subtitle,diff,module){return{kaynak:type,baslik:title,altBaslik:subtitle||'',gunFarki:diff,module,git:route(module)}}
function scanTasks(id,days){return arr('gorevler').filter(x=>(x.sorumluOgretmenIdler||[]).includes(id)&&!['tamamlandi','Tamamlandı','Tamamlandi'].includes(x.durum)&&x.sonTarih).map(x=>reminder('gorev',`Görev: ${x.baslik||'Görev'}`,x.aciklama,dayDiff(x.sonTarih),'dashboard')).filter(x=>x.gunFarki<=days)}
function scanDocuments(id,days){return arr('evrakTakibi').filter(x=>(x.sorumluOgretmenIdler||[]).includes(id)&&!['Tamamlandı','Tamamlandi','Arşivlendi','Arsivlendi'].includes(x.durum)&&x.tarih).map(x=>reminder('evrak',`Evrak: ${x.evrakAdi||x.baslik||'Evrak'}`,x.aciklama,dayDiff(x.tarih),'documents')).filter(x=>x.gunFarki<=days)}
function scanDuty(id){const today=isoToday(),places=arr('nobetYerleri');return arr('nobetAtamalari').filter(x=>x.tarih===today&&x.ogretmenId===id&&!x.defterDolduruldu).map(x=>reminder('nobet',`Bugün nöbetçisiniz: ${places.find(p=>p.id===x.yerId)?.ad||x.yerAdi||'Nöbet'}`,'Nöbet defterini doldurmayı unutmayın',0,'management'))}
function scanMonthly(id,days){const out=[];Object.entries(MONTHLY).forEach(([type,cfg])=>arr(type).forEach(row=>{if(!belongs(row,id,cfg.teacherField))return;cfg.aylar.forEach((shortName,i)=>{if((row.kontroller||[])[cfg.start+i])return;const target=academicMonthDeadline(shortName),diff=dayDiff(target);if(diff>=-400&&diff<=days)out.push(reminder(type,`${cfg.label} — ${shortName}`,row.ders||row.sinif||row.rapor||'',diff,'tools'))})}));return out}
function scanPeriods(id,days){const out=[];for(const type of ['zumre','sok'])arr(type).forEach(row=>{if(row.ogretmenId!==id)return;['tarih1','tarih2','tarih3'].forEach((field,i)=>{const target=row[field];if(!target||(row.kontroller||[])[i])return;const diff=dayDiff(target);if(diff<=days)out.push(reminder(type,`${type==='zumre'?'Zümre Toplantısı':'ŞÖK'} — ${['1. Dönem','2. Dönem','Yıl Sonu'][i]}: ${row.brans||row.konu||row.sinif||''}`.trim(),row.sinif&&row.brans?row.sinif:'',diff,'tools'))})});return out}
function scanOneOff(id,days){const out=[];ONE_OFF.forEach(cfg=>arr(cfg.type).forEach(row=>{if(!belongs(row,id,cfg.teacherField))return;const target=row[cfg.field];if(!target||(row.kontroller||[])[cfg.index])return;const diff=dayDiff(target);if(diff<=days)out.push(reminder(cfg.type,cfg.label,row.ad||row.brans||row.sinif||'',diff,'tools'))}));return out}
function scanSpecialDays(id,days){return arr('belirliGunler').filter(x=>(x.ogretmenIdler||[]).includes(id)&&!(x.kontroller||[])[0]&&x.tarihBaslangic).map(x=>reminder('belirliGunler',`Belirli Gün/Hafta: ${x.ad||''}`,'',dayDiff(x.tarihBaslangic),'tools')).filter(x=>x.gunFarki<=days)}
function scanExams(id,days){return arr('sinavlar').filter(x=>x.ogretmenId===id&&x.tarih).map(x=>reminder('sinav',`Yazılı Sınav: ${x.ders||''} ${x.sinif||''}`.trim(),x.saat?`Saat: ${x.saat}`:'',dayDiff(x.tarih),'academic')).filter(x=>x.gunFarki>=0&&x.gunFarki<=days)}
function linkedTeacherIds(row){if(Array.isArray(row?.ogretmenIdler))return row.ogretmenIdler;if(row?.ogretmenId)return[row.ogretmenId];return[]}
function linkedDate(type,row,index){if(!row)return null;if(type==='zumre'||type==='sok')return row[`tarih${index+1}`]||null;if(type==='sosyalKulupler'){if(index===0)return row.yillikPlanTarihi||null;if(index===1)return row.toplumHizmetiTarihi||null;const short=MONTHLY.sosyalKulupler.aylar[index-2];return short?academicMonthDeadline(short):null}if(type==='rehberlik'){if(index===0)return row.yillikPlanTarihi||null;const short=MONTHLY.rehberlik.aylar[index-1];return short?academicMonthDeadline(short):null}if(type==='bepPlani')return index===0?(row.yillikDersPlaniTarihi||null):(row.bepPlaniTarihi||null);if(type==='maarifRapor'){const short=MONTHLY.maarifRapor.aylar[index];return short?academicMonthDeadline(short):null}if(type==='belirliGunler')return row.tarihBaslangic||null;return row.tarih||row.sonTarih||null}
function itemTargetsTeacher(item,id){if(item.baglıEvrak){const ids=item.baglıEvrak.kayitIdler||(item.baglıEvrak.kayitId?[item.baglıEvrak.kayitId]:[]);return ids.some(rid=>linkedTeacherIds(arr(item.baglıEvrak.tip).find(x=>x.id===rid)).includes(id))}if(!item.hedefTip||item.hedefTip==='herkes')return true;if(item.hedefTip==='ozel')return(item.hedefOgretmenIdler||[]).includes(id);const teacher=arr('ogretmenler').find(x=>x.id===id);if(!teacher||typeof window.kademeFiiliListesi!=='function')return true;return window.kademeFiiliListesi(teacher).includes(item.hedefTip)}
function scanChecklists(id,days){const out=[];for(const list of arr('kontrolListeleri').filter(x=>x.yayinda!==false)){const complete=new Set((arr('kontrolListeTamamlama').find(x=>x.id===`${id}_${list.id}`||x.ogretmenId===id&&x.listeId===list.id)?.tamamlananMaddeIdler)||[]);for(const item of list.maddeler||[]){if(!itemTargetsTeacher(item,id))continue;let target=item.tarih,done=complete.has(item.id);if(item.baglıEvrak){const ids=item.baglıEvrak.kayitIdler||(item.baglıEvrak.kayitId?[item.baglıEvrak.kayitId]:[]),indices=item.baglıEvrak.kontrolIndexler||(item.baglıEvrak.kontrolIndex!==undefined?[item.baglıEvrak.kontrolIndex]:[]),row=ids.map(rid=>arr(item.baglıEvrak.tip).find(x=>x.id===rid)).find(x=>x&&linkedTeacherIds(x).includes(id));if(!row)continue;const relevant=indices.length?indices:[0];done=relevant.every(i=>(row.kontroller||[])[i]);target=relevant.map(i=>linkedDate(item.baglıEvrak.tip,row,i)).filter(Boolean).sort()[0]||null}if(!target||done)continue;const diff=dayDiff(target);if(diff<=days)out.push(reminder('kontrolListesi',`Kontrol Listesi: ${list.ad||'Liste'}`,item.metin||'',diff,'tools'))}}return out}
function collectReminders(){const id=teacherId();if(!id)return[];const days=Number(reminderSettings().gunSayisi)||3;return[...scanTasks(id,days),...scanDocuments(id,days),...scanDuty(id),...scanMonthly(id,days),...scanPeriods(id,days),...scanOneOff(id,days),...scanSpecialDays(id,days),...scanExams(id,days),...scanChecklists(id,days)].filter(x=>Number.isFinite(x.gunFarki)).sort((a,b)=>a.gunFarki-b.gunFarki)}
function holidayMode(){return !!(arr('dersSaatleri').find(x=>x.id==='ayarlar')||arr('dersSaatleri')[0]||{}).tatilModu}
async function reminderSnoozed(){const u=user().uid;if(!u||!window.KorukLocalFirst)return false;const until=await KorukLocalFirst.meta(u,'reminderSnoozeUntil');return Number(until||0)>Date.now()}
async function snoozeReminders(){const hours=Number(reminderSettings().erteleSaat)||4,u=user().uid;if(u&&window.KorukLocalFirst)await KorukLocalFirst.meta(u,'reminderSnoozeUntil',Date.now()+hours*3600000);closeReminderPopup()}
function closeReminderPopup(){document.getElementById('dashboardReminderModal')?.remove()}
function reminderStatus(r){if(r.gunFarki<0)return{label:`${Math.abs(r.gunFarki)} gün gecikti`,cls:'ka-badge--danger'};if(r.gunFarki===0)return{label:'Bugün son gün',cls:'ka-badge--warning'};return{label:`${r.gunFarki} gün kaldı`,cls:''}}
function openReminderPopup(items){closeReminderPopup();const settings=reminderSettings(),ov=document.createElement('div');ov.id='dashboardReminderModal';ov.className='ka-modal-backdrop';ov.innerHTML=`<section class="ka-modal"><div class="ka-modal__header"><div><strong>🔔 Hatırlatmalarınız</strong><div class="ka-muted">${items.length} bekleyen madde</div></div><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-reminder-close>Kapat</button></div><div class="ka-modal__body ka-stack">${items.map((r,i)=>{const s=reminderStatus(r);return`<button class="ka-btn ka-btn--secondary" type="button" data-reminder-index="${i}"><span class="ka-grow"><strong>${esc(r.baslik)}</strong>${r.altBaslik?`<small>${esc(r.altBaslik)}</small>`:''}</span><span class="ka-badge ${s.cls}">${esc(s.label)}</span></button>`}).join('')}</div><div class="ka-modal__footer"><button class="ka-btn ka-btn--secondary" type="button" data-reminder-snooze>⏰ ${Number(settings.erteleSaat)||4} saat ertele</button><button class="ka-btn" type="button" data-reminder-ok>Tamam</button></div></section>`;document.body.appendChild(ov);ov.querySelector('[data-reminder-close]').onclick=closeReminderPopup;ov.querySelector('[data-reminder-ok]').onclick=closeReminderPopup;ov.querySelector('[data-reminder-snooze]').onclick=snoozeReminders;ov.querySelectorAll('[data-reminder-index]').forEach(btn=>btn.onclick=()=>{const r=items[Number(btn.dataset.reminderIndex)];closeReminderPopup();r?.git?.()})}
async function maybeShowReminders(){if(reminderShown||holidayMode()||await reminderSnoozed())return;const items=collectReminders();if(!items.length)return;reminderShown=true;openReminderPopup(items)}
async function prepareReminderData(){if(!window.SyncEngine||!window.COL)return;const types=[];for(const[type,colKey]of Object.entries(REMINDER_DEFS)){const col=COL[colKey];if(!col)continue;SyncEngine.register(type,col);types.push(type)}if(types.length){await SyncEngine.localHydrate(types);SyncEngine.schedule(120)}}
function render(){if(!mounted)return;const root=document.querySelector('[data-dashboard-module]');if(!root)return;const parent=root.parentElement||document.getElementById('v2ModuleRoot'),signature=cards().map(x=>x.key).join('|'),role=isAdmin()?'admin':'teacher';if(root.dataset.cardSignature!==signature||root.dataset.dashboardRole!==role){parent.innerHTML=shell();bindPresentation(parent);return}const scrollY=window.scrollY;parent.innerHTML=shell();bindPresentation(parent);if(scrollY>0)requestAnimationFrame(()=>window.scrollTo(0,scrollY))}
function subscribe(){unsubs.forEach(f=>{try{f()}catch(_){}});unsubs=[];['data.ogretmenler','data.dersProgrami','data.siniflar','data.veliler','data.servisler','data.hatirlaticilar','data.gorevler','data.sinavlar','data.denemeSinavlari','data.duyurular','data.haberler','data.anketler','data.nobetAtamalari','data.nobetYerleri','data.personelIzinler','data.ogretmenIzinleri','data.notlar','data.appConfig','session.user'].forEach(p=>{const u=window.AppStore?.subscribe?.(p,()=>requestAnimationFrame(render));if(u)unsubs.push(u)})}
async function mount(root=document.getElementById('v2ModuleRoot')){if(!root)return false;mounted=true;root.innerHTML=shell();bindPresentation(root);subscribe();await prepareReminderData();render();requestAnimationFrame(()=>maybeShowReminders());return true}
function unmount(){mounted=false;closeReminderPopup();unsubs.forEach(f=>{try{f()}catch(_){}});unsubs=[]}
window.DashboardModule={mount,unmount,render,collectReminders,maybeShowReminders,prepareReminderData};
window.uygulamaBaslat=function(){window.AppLoader?.load?.('dashboard').then(()=>mount()).catch(e=>console.warn('[Dashboard]',e?.message||e))};
window.addEventListener('koruk:module-ready',e=>{if(e.detail?.name==='dashboard')mount()});
window.addEventListener('koruk:app-config-changed',()=>requestAnimationFrame(render));
})();
;
